/*
 * nn.h -- real neural network inference, chunked so a deadline can
 *         interrupt it.
 *
 * WHAT THIS REPLACED
 * ------------------
 * The engine used to burn a calibrated number of microseconds per chunk.
 * The scheduling behaviour that demonstrated was real; the AI was not.
 * This does the actual arithmetic: three trained MLPs (server/nn_weights.h,
 * generated by tools/train_detector.py from MNIST) scanned over a frame as
 * a sliding window.
 *
 * It is a detector in the real sense -- it reports what it found, how
 * confident it is, and where in the frame. It is not a pedestrian
 * detector, and the README says so; a 14x14 MLP on digits stands in for
 * the vision model a shipping system would run. What is no longer standing
 * in is the inference, the cost, or the accuracy:
 *
 *     small   93.64% test accuracy    3296 MACs/patch   36 patches/frame
 *     medium  95.30%                 13184             144
 *     large   97.28%                 33920             324
 *
 * Those accuracies are measured on the 10k MNIST test set, and they are
 * what the server reports as `confidence`. The three numbers that field
 * used to carry were invented.
 *
 * WHY THE SLIDING WINDOW MATTERS HERE
 * -----------------------------------
 * A single 196-input MLP runs in microseconds, which is far too fast to
 * have a deadline problem -- the whole premise needs work that can
 * plausibly miss 20ms. Scanning a frame is how classical detection
 * actually works, it multiplies the cost by the number of windows, and
 * critically it gives a natural chunk boundary every few patches.
 *
 * That last part is the requirement docs/architecture.md set out and could
 * not meet with llama.cpp: a runtime that only returns at the end of a
 * 300ms generation is preemptible but cannot be *degraded* intelligently.
 * Here the engine can stop between any two patches and answer with the
 * best detection so far, which is exactly what a brake controller wants.
 */
#ifndef TRIAGE_NN_H_
#define TRIAGE_NN_H_

#include <stdint.h>

#include "triage_proto.h"

/* Loads nothing -- the weights are compiled in -- but measures how long a
 * patch takes for each tier, which is how the engine sizes its chunks and
 * seeds its cost model. Call once at startup. */
void     nn_init(void);

/* Measured microseconds to evaluate one patch at this tier. */
uint64_t nn_us_per_patch(triage_tier_t tier);

/* Total sliding-window positions a frame has at this tier's stride. */
unsigned nn_patches(triage_tier_t tier);

/* How many patches to do per chunk so a chunk costs about target_us.
 * At least 1: a chunk always makes progress. */
unsigned nn_patches_per_chunk(triage_tier_t tier, uint64_t target_us);

/* Measured accuracy of this tier on the MNIST test set, 0..1000. */
unsigned nn_accuracy(triage_tier_t tier);

/*
 * A scan in progress.
 *
 * Held per thread rather than passed around, because a resource manager
 * pool thread serves exactly one request at a time -- so thread-local
 * state needs no allocation, no locking, and no change to the engine's
 * chunk interface.
 */
void     nn_scan_begin(triage_tier_t tier, uint32_t frame_sel);
int      nn_scan_complete(void);

/* Evaluate up to n more patches. Returns how many it actually did, which
 * is less than n at the end of the frame. */
unsigned nn_scan_step(unsigned n);

/* Best detection so far: class, confidence 0..1000, and where it was
 * found. Valid at any point, which is the point -- a request that stops
 * early still has an answer. */
int      nn_scan_best_class(void);
unsigned nn_scan_best_score(void);
int      nn_scan_best_x(void);
int      nn_scan_best_y(void);
unsigned nn_scan_done_patches(void);

/* Ground truth for the frame being scanned, so an on-target test can
 * score the server's own output instead of trusting it. */
int      nn_scan_truth_class(void);

/* Number of frames compiled in. */
unsigned nn_frame_count(void);

#endif /* TRIAGE_NN_H_ */
